          {messages.length === 0 && (
             <div className="flex flex-col items-center justify-center h-full space-y-4 opacity-40">
                <div className="w-16 h-16 border-2 border-dashed flex items-center justify-center animate-pulse" style={{ borderColor: 'var(--border-color)' }}>
                   <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812-1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                  </svg>
                </div>
                <div className="text-center space-y-2">
                  <p className="text-[12px] uppercase font-bold tracking-[0.2em]" style={{ color: 'var(--text-color)' }}>
