import { GoogleGenAI, Type, Chat, GenerateContentResponse } from "@google/genai";
import { UserDiagnostics, Recipe, DetectedItem } from "../types";
import { i18n } from "../translations";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getSystemInstruction = (lang: string) => {
  const t = i18n[lang as keyof typeof i18n] || i18n['English'];
  const safetyHeader = t.safetyProtocol;

  return `Sei Chef Omoikane. 
Esperto in alta cucina e biochimica alimentare.

REGOLE DI COMUNICAZIONE:
1. Parla in modo conciso, preciso e chiaro. 
2. Sii breve. Evita spiegazioni prolisse.
3. Lingua: ${lang}.

LOGICA DI VALUTAZIONE:
Valuta rigorosamente condizioni mediche, allergie e REGIMI ALIMENTARI.
Se l'utente è sano, focalizzati sulla promozione della salute (no eccessi di zuccheri, sodio, ultra-processati).

STRUMENTI MAPPE (BIO-LOCATOR):
Quando usi googleMaps, trova locali raggiungibili entro 20 minuti a piedi.
Cross-referenzia i locali con la condizione medica dell'utente.
Fornisci una classificazione cromatica per ogni locale trovato:
- SAFE (Verde): Ideale per la salute dell'utente.
- WARNING (Giallo): Accettabile ma richiede cautela.
- FORBIDDEN (Rosso): Pericoloso o incompatibile con la salute/regime dell'utente.
SPIEGA SEMPRE IL PERCHÉ della classificazione.
`;
};

export const generateRecipe = async (diagnostics: UserDiagnostics): Promise<Recipe> => {
  const t = i18n[diagnostics.language];
  const healthInfo = diagnostics.healthProfile.trim() || t.healthyStatus;

  const prompt = `Genera ricetta per: ${diagnostics.targetDish}. 
  Lingua: ${diagnostics.language}.
  Profilo Salute (Allergie/Patologie): ${healthInfo}. 
  Ingredienti forniti: ${diagnostics.ingredients}.
  Specifiche/Obiettivi: ${diagnostics.additionalSpecs}.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language),
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          medicalAnalysis: { type: Type.STRING },
          cookingTime: { type: Type.STRING, description: "Estimated total cooking time" },
          ingredients: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                amount: { type: Type.STRING },
                function: { type: Type.STRING }
              },
              required: ["name", "amount", "function"]
            }
          },
          procedure: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          scienceCheck: { type: Type.STRING },
          macros: {
            type: Type.OBJECT,
            properties: {
              calories: { type: Type.STRING },
              protein: { type: Type.STRING },
              carbs: { type: Type.STRING },
              fats: { type: Type.STRING },
              fiber: { type: Type.STRING }
            },
            required: ["calories", "protein", "carbs", "fats", "fiber"]
          }
        },
        required: ["title", "medicalAnalysis", "ingredients", "procedure", "scienceCheck", "macros", "cookingTime"]
      }
    }
  });

  return JSON.parse(response.text);
};

export const createRecipeChat = (recipe: Recipe, diagnostics: UserDiagnostics): Chat => {
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language) + `\nStai assistendo l'utente per la ricetta "${recipe.title}".`,
    },
  });
};

export const analyzeHealthOrMenu = async (
  query: string, 
  diagnostics: UserDiagnostics, 
  imageBase64?: string
): Promise<{ text: string, detections?: DetectedItem[], sources?: { title: string, uri: string }[] }> => {
  const parts: any[] = [{ text: query }];

  if (imageBase64) {
    parts.push({
      inlineData: {
        data: imageBase64.split(',')[1],
        mimeType: "image/jpeg"
      }
    });
  }

  const t = i18n[diagnostics.language];
  const healthInfo = diagnostics.healthProfile.trim() || t.healthyStatus;
  const prompt = `Analisi basata su:\nQuery: ${query}\nProfilo Salute (Allergie/Patologie): ${healthInfo}\nObiettivi/Regimi: ${diagnostics.additionalSpecs}\n\nEsegui un'analisi nutrizionale dei piatti. Se l'utente è sano, focalizzati su zuccheri, sodio e grassi saturi. Se l'immagine mostra un prodotto commerciale, cerca su Google i suoi valori nutrizionali reali. Usa detections per indicare visivamente la salubrità con i colori.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: { parts: [...parts, { text: prompt }] },
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language),
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          text: { type: Type.STRING, description: "Analisi testuale dettagliata che spiega perché un cibo è sano o meno." },
          detections: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                status: { type: Type.STRING, enum: ['SAFE', 'WARNING', 'FORBIDDEN'] },
                box_2d: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                reason: { type: Type.STRING }
              },
              required: ["name", "status", "box_2d", "reason"]
            }
          }
        },
        required: ["text"]
      }
    }
  });

  const parsed = JSON.parse(response.text);

  const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
    ?.map(chunk => {
      if (chunk.web) {
        return {
          title: chunk.web.title || 'Source',
          uri: chunk.web.uri || ''
        };
      }
      return null;
    })
    ?.filter(Boolean) as { title: string; uri: string }[] || [];

  return {
    text: parsed.text,
    detections: parsed.detections,
    sources: sources.length > 0 ? sources : undefined
  };
};

export const analyzeNearbyPlaces = async (
  query: string,
  diagnostics: UserDiagnostics,
  lat: number,
  lng: number
): Promise<{ text: string, sources: { title: string, uri: string }[] }> => {
  const t = i18n[diagnostics.language];
  const healthInfo = diagnostics.healthProfile.trim() || t.healthyStatus;

  const prompt = `Trova locali (ristoranti, bar, caffè) di tipo "${query}" che siano raggiungibili a piedi in massimo 20 minuti dalla mia posizione (${lat}, ${lng}). 
  Per ogni locale trovato, verifica il menu o il tipo di cucina tramite ricerca web.
  Classificali in base al mio profilo salute: ${healthInfo}.
  Obiettivi/Regimi: ${diagnostics.additionalSpecs}.
  Usa i colori VERDE (Ideale), GIALLO (Attenzione), ROSSO (Vietato).
  Mostra sempre il nome del locale e il perché della valutazione.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language),
      tools: [{ googleMaps: {} }, { googleSearch: {} }],
      toolConfig: {
        retrievalConfig: {
          latLng: { latitude: lat, longitude: lng }
        }
      }
    }
  });

  // Extract Map/Web chunks
  const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
    ?.map(chunk => {
      if (chunk.maps) {
        return {
          title: chunk.maps.title || 'Map Location',
          uri: chunk.maps.uri || ''
        };
      } else if (chunk.web) {
        return {
          title: chunk.web.title || 'Web Source',
          uri: chunk.web.uri || ''
        };
      }
      return null;
    })
    ?.filter(Boolean) as { title: string; uri: string }[] || [];

  return {
    text: response.text || "No analysis provided.",
    sources
  };
};

