import React, { useState, useEffect } from 'react';
import { Translations, UserDiagnostics } from '../types';
import { analyzeNearbyPlaces } from '../services/geminiService';

interface Props {
  t: Translations;
  diagnostics: UserDiagnostics;
  onUpdate: (updates: Partial<UserDiagnostics>) => void;
}

const MapsTerminal: React.FC<Props> = ({ t, diagnostics, onUpdate }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isLocating, setIsLocating] = useState(false);
  const [result, setResult] = useState<{ text: string, sources: { title: string, uri: string }[] } | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [localHealth, setLocalHealth] = useState(diagnostics.healthProfile);

  useEffect(() => {
    setLocalHealth(diagnostics.healthProfile);
  }, [diagnostics.healthProfile]);

  const handleUpdateHealth = (val: string) => {
    setLocalHealth(val);
    onUpdate({ healthProfile: val });
  };

  const handleActivateScan = () => {
    setIsLocating(true);
    setError(null);
    setResult(null);

    if (!navigator.geolocation) {
      setError(t.gpsError);
      setIsLocating(false);
      return;
    }

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        try {
          const { latitude, longitude } = position.coords;
          const data = await analyzeNearbyPlaces(
            searchQuery || "restaurants and cafes",
            { ...diagnostics, healthProfile: localHealth },
            latitude,
            longitude
          );
          setResult(data);
        } catch (err) {
          setError(t.error);
        } finally {
          setIsLocating(false);
        }
      },
      (err) => {
        setError(`${t.gpsError} (${err.message})`);
        setIsLocating(false);
      }
    );
  };

  return (
    <div className="flex flex-col gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="header-font text-lg font-bold tracking-tighter flex items-center gap-3" style={{ color: 'var(--text-color)' }}>
        <div className="w-1.5 h-1.5 rounded-full bg-current animate-pulse"></div>
        {t.mapsTitle}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Health Profile Card */}
        <div className="glow-border p-6 bg-black/30 flex flex-col gap-4" style={{ borderColor: 'var(--border-color)' }}>
          <label className="text-[10px] font-black uppercase tracking-widest opacity-60">{t.healthProfile}</label>
          <textarea
            className="bg-transparent border-b border-white/20 outline-none p-2 text-sm font-mono min-h-[120px] resize-none"
            placeholder={t.healthProfilePlace}
            value={localHealth}
            onChange={(e) => handleUpdateHealth(e.target.value)}
            style={{ color: 'var(--text-color)' }}
          />
        </div>

        {/* Search Context Card */}
        <div className="glow-border p-6 bg-black/30 flex flex-col gap-4" style={{ borderColor: 'var(--border-color)' }}>
          <label className="text-[10px] font-black uppercase tracking-widest opacity-60">{t.targetDish}</label>
          <input
            type="text"
            className="bg-transparent border-b border-white/20 outline-none p-2 text-sm font-mono"
            placeholder={t.mapsSearchPlace}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            style={{ color: 'var(--text-color)' }}
          />
          <div className="flex-1"></div>
          <p className="text-[10px] font-mono italic opacity-50 leading-relaxed">
            {t.mapsExplainer}
          </p>
        </div>
      </div>

      <div className="flex justify-center mt-4">
        <button
          onClick={handleActivateScan}
          disabled={isLocating}
          className={`
            relative group px-12 py-6 header-font font-black text-xs uppercase tracking-[0.4em] 
            transition-all duration-300 border-2 active:scale-95 disabled:opacity-40
            ${isLocating ? 'animate-pulse' : 'hover:bg-white hover:text-black hover:shadow-[0_0_30px_rgba(255,255,255,0.3)]'}
          `}
          style={{ 
            borderColor: 'var(--text-color)', 
            color: 'var(--text-color)',
            backgroundColor: isLocating ? 'rgba(255,255,255,0.1)' : 'transparent'
          }}
        >
          {isLocating ? t.processing : t.gpsBtn}
          <div className="absolute inset-0 border border-white/10 group-hover:scale-110 transition-transform -z-10"></div>
        </button>
      </div>

      {error && (
        <div className="p-4 border border-red-500/30 text-red-500 text-[10px] font-mono uppercase bg-red-500/5">
          [GPS_FAILURE] {error}
        </div>
      )}

      {result && (
        <div className="glow-border p-8 bg-black/40 font-mono space-y-6 animate-in fade-in zoom-in-95 duration-500" style={{ borderColor: 'var(--border-color)' }}>
          <div className="flex justify-between items-center border-b pb-4" style={{ borderColor: 'var(--border-color)' }}>
            <span className="text-[9px] font-black uppercase tracking-widest opacity-50">Analysis Protocol // Geo-Safety</span>
            <span className="text-[10px] text-green-500 animate-pulse">● LINK_ACTIVE</span>
          </div>

          <div className="text-sm leading-relaxed whitespace-pre-wrap">
            {result.text}
          </div>

          {result.sources.length > 0 && (
            <div className="pt-6 border-t" style={{ borderColor: 'var(--border-color)' }}>
              <h4 className="text-[10px] font-black uppercase tracking-widest mb-4 opacity-50">{t.webSources}</h4>
              <div className="flex flex-col gap-3">
                {result.sources.map((source, idx) => (
                  <a 
                    key={idx} 
                    href={source.uri} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="text-[11px] text-blue-400 hover:text-blue-300 transition-colors flex items-center gap-2 group"
                  >
                    <svg className="w-3 h-3 opacity-40 group-hover:opacity-100" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                    </svg>
                    <span className="border-b border-transparent group-hover:border-blue-300">{source.title}</span>
                  </a>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default MapsTerminal;

