import React, { useState, useEffect, useCallback } from 'react';
import { Translations, UserDiagnostics } from '../types';
import { analyzeNearbyPlaces } from '../services/geminiService';
import { LANGUAGES } from '../App';

interface Props {
  t: Translations;
  diagnostics: UserDiagnostics;
  onUpdate: (updates: Partial<UserDiagnostics>) => void;
}

const MapsTerminal: React.FC<Props> = ({ t, diagnostics, onUpdate }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isLocating, setIsLocating] = useState(false);
  const [result, setResult] = useState<{ text: string, sources: { title: string, uri: string }[] } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [activeMicField, setActiveMicField] = useState<string | null>(null);

  const [localHealth, setLocalHealth] = useState(diagnostics.healthProfile);

  useEffect(() => {
    setLocalHealth(diagnostics.healthProfile);
  }, [diagnostics.healthProfile]);

  const selectedLang = LANGUAGES.find(l => l.code === diagnostics.language);

  const handleUpdateHealth = (val: string) => {
    setLocalHealth(val);
    onUpdate({ healthProfile: val });
  };

  const handleInputFocus = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const target = e.target;
    setTimeout(() => {
      target.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 300);
  };

  const startVoiceInput = useCallback((field: 'health' | 'search') => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) return;
    const recognition = new SpeechRecognition();
    recognition.lang = selectedLang?.speechCode || 'it-IT';
    recognition.onstart = () => setActiveMicField(field);
    recognition.onend = () => setActiveMicField(null);
    recognition.onerror = () => setActiveMicField(null);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      if (field === 'health') {
        const newValue = localHealth ? `${localHealth} ${transcript}` : transcript;
        handleUpdateHealth(newValue);
      } else {
        const newValue = searchQuery ? `${searchQuery} ${transcript}` : transcript;
        setSearchQuery(newValue);
      }
    };
    recognition.start();
  }, [selectedLang, localHealth, searchQuery]);

  const handleActivateScan = () => {
    setIsLocating(true);
    setError(null);
    setResult(null);

    if (!navigator.geolocation) {
      setError(t.gpsError);
      setIsLocating(false);
      return;
    }

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        try {
          const { latitude, longitude } = position.coords;
          const data = await analyzeNearbyPlaces(
            searchQuery || "restaurants and cafes",
            { ...diagnostics, healthProfile: localHealth },
            latitude,
            longitude
          );
          setResult(data);
        } catch (err) {
          setError(t.error);
        } finally {
          setIsLocating(false);
        }
      },
      (err) => {
        setError(`${t.gpsError} (${err.message})`);
        setIsLocating(false);
      }
    );
  };

  const MicButton = ({ isActive, onClick }: { isActive: boolean, onClick: () => void }) => (
    <button
      type="button"
      onClick={onClick}
      className={`absolute right-0 top-1/2 -translate-y-1/2 transition-all p-3 flex items-center justify-center rounded-full hover:bg-white/10 ${isActive ? 'recording-pulse scale-110' : 'opacity-40 hover:opacity-100'}`}
    >
      <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
        <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/>
      </svg>
    </button>
  );

  return (
    <div className="flex flex-col gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="header-font text-lg font-bold tracking-tighter flex items-center gap-3" style={{ color: 'var(--text-color)' }}>
        <div className="w-1.5 h-1.5 rounded-full bg-current animate-pulse"></div>
        {t.mapsTitle}
      </div>

      <div className="grid grid-cols-1 gap-8">
        {/* CLINICAL PROFILE INPUT (MATCHES CHECK STYLE) */}
        <div className="glow-border p-6 bg-black/30 border-2 transition-all duration-500 shadow-xl" style={{ borderColor: 'var(--border-color)' }}>
          <div className="flex justify-between items-center mb-6">
            <div className="text-[11px] font-black uppercase tracking-[0.3em] flex items-center gap-3">
              <span className="w-3 h-3 rounded-full bg-green-500 opacity-50 shadow-[0_0_10px_rgba(34,197,94,0.3)]"></span>
              {t.activeClinicalProfile}
            </div>
          </div>
          <div className="relative group focus-within:shadow-[inset_0_0_20px_rgba(255,255,255,0.05)] transition-all">
            <textarea 
              placeholder={t.healthProfilePlace} 
              onFocus={handleInputFocus} 
              className="w-full bg-transparent border-b border-white/20 text-[13px] py-4 pr-16 outline-none focus:border-white/60 transition-all font-mono min-h-[100px] resize-none leading-relaxed" 
              style={{ color: 'var(--text-color)' }} 
              value={localHealth} 
              onChange={(e) => handleUpdateHealth(e.target.value)} 
            />
            <MicButton isActive={activeMicField === 'health'} onClick={() => startVoiceInput('health')} />
          </div>
        </div>

        {/* SEARCH CONTEXT BOX */}
        <div className="glow-border p-8 bg-black/30 border-2" style={{ borderColor: 'var(--border-color)' }}>
          <div className="text-[10px] font-black uppercase tracking-[0.2em] mb-4 opacity-60 flex items-center gap-2">
            <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
            {t.targetDish}
          </div>
          <div className="relative group">
            <input
              type="text"
              onFocus={handleInputFocus}
              className="w-full bg-transparent border-b border-white/20 outline-none py-4 pr-16 text-[15px] font-mono focus:border-white/60 transition-all"
              placeholder={t.mapsSearchPlace}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              style={{ color: 'var(--text-color)' }}
            />
            <MicButton isActive={activeMicField === 'search'} onClick={() => startVoiceInput('search')} />
          </div>
          <div className="mt-8 p-4 bg-white/5 border border-white/10 rounded">
            <p className="text-[10px] font-mono italic opacity-70 leading-relaxed text-center">
              {t.mapsExplainer}
            </p>
          </div>
        </div>
      </div>

      <div className="flex justify-center mt-6">
        <button
          onClick={handleActivateScan}
          disabled={isLocating}
          className={`
            relative group px-16 py-8 header-font font-black text-sm uppercase tracking-[0.4em] 
            transition-all duration-300 border-2 active:scale-95 disabled:opacity-40
            ${isLocating ? 'animate-pulse bg-white/5' : 'hover:bg-white hover:text-black hover:shadow-[0_0_40px_rgba(255,255,255,0.4)]'}
          `}
          style={{ 
            borderColor: 'var(--text-color)', 
            color: 'var(--text-color)',
            backgroundColor: isLocating ? undefined : 'transparent'
          }}
        >
          {isLocating ? t.processing : t.gpsBtn}
          <div className="absolute inset-[-4px] border border-white/5 scale-105 opacity-0 group-hover:opacity-100 transition-all duration-500"></div>
        </button>
      </div>

      {error && (
        <div className="p-4 border-2 border-red-500/50 text-red-500 text-[11px] font-bold font-mono uppercase bg-red-500/10 text-center animate-bounce">
          [CRITICAL_GPS_FAILURE] // {error}
        </div>
      )}

      {result && (
        <div className="glow-border p-8 bg-black/40 font-mono space-y-6 animate-in fade-in zoom-in-95 duration-500 border-2" style={{ borderColor: 'var(--border-color)' }}>
          <div className="flex justify-between items-center border-b pb-4" style={{ borderColor: 'var(--border-color)' }}>
            <span className="text-[9px] font-black uppercase tracking-[0.3em] opacity-50">BIO-GASTRONOMIC_MATRIX // GEO_SYNC</span>
            <span className="text-[10px] text-green-500 animate-pulse font-bold tracking-widest flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-green-500"></span>
              DATA_LINK_ESTABLISHED
            </span>
          </div>

          <div className="text-[14px] leading-relaxed whitespace-pre-wrap border-l-2 pl-6 py-2" style={{ borderColor: 'rgba(255,255,255,0.1)' }}>
            {result.text}
          </div>

          {result.sources.length > 0 && (
            <div className="pt-8 border-t" style={{ borderColor: 'var(--border-color)' }}>
              <h4 className="text-[10px] font-black uppercase tracking-widest mb-6 opacity-40 flex items-center gap-3">
                <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/></svg>
                {t.webSources}
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {result.sources.map((source, idx) => (
                  <a 
                    key={idx} 
                    href={source.uri} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="p-3 border border-white/10 text-[11px] text-blue-400 hover:bg-white/5 transition-all flex items-center gap-3 group"
                  >
                    <svg className="w-4 h-4 opacity-40 group-hover:opacity-100 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                    </svg>
